import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/15-Plugin_Architecture.html","title":"插件化与动态加载设计（存储/扩展模块）","lang":"en-US","frontmatter":{},"filePathRelative":"15-Plugin_Architecture.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`15-Plugin_Architecture.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="插件化与动态加载设计-存储-扩展模块" tabindex="-1"><a class="header-anchor" href="#插件化与动态加载设计-存储-扩展模块"><span>插件化与动态加载设计（存储/扩展模块）</span></a></h1><blockquote><p>目的：以 Spring Boot 的“组件/Starter”理念为参考，为 Apollo C++ 框架定义动态加载/插件化机制，支持 MySQL/MongoDB/Redis 等可插拔数据源以及其他扩展模块。</p></blockquote><h2 id="_1-设计目标" tabindex="-1"><a class="header-anchor" href="#_1-设计目标"><span>1. 设计目标</span></a></h2><ol><li><strong>按需加载</strong>：不同进程仅加载所需插件，减少主程序体积与依赖。</li><li><strong>统一接口</strong>：插件通过标准接口注册 Bean，业务逻辑无需关注具体实现。</li><li><strong>跨平台</strong>：在 Windows（DLL）与 Linux/macOS（SO/DYLIB）上使用统一的加载封装。</li><li><strong>热插拔（可选）</strong>：后续可支持运行时卸载/替换，但初期以启动期加载为主。</li><li><strong>安全/稳定</strong>：限定导出接口，避免 ABI 不兼容；必要时提供签名/校验。</li></ol><h2 id="_2-sharedlibrary-封装" tabindex="-1"><a class="header-anchor" href="#_2-sharedlibrary-封装"><span>2. SharedLibrary 封装</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">SharedLibrary</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token function">SharedLibrary</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token operator">~</span><span class="token function">SharedLibrary</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token function">Unload</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">Load</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> path<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">void</span><span class="token operator">*</span> <span class="token function">GetSymbol</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> name<span class="token punctuation">)</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">Unload</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">ifdef</span> <span class="token expression">_WIN32</span></span></span>
<span class="line">    HMODULE handle_ <span class="token operator">=</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">else</span></span></span>
<span class="line">    <span class="token keyword">void</span><span class="token operator">*</span> handle_ <span class="token operator">=</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">endif</span></span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>Windows: <code>LoadLibraryA</code>, <code>GetProcAddress</code>, <code>FreeLibrary</code>, 并记录 <code>GetLastError()</code>。</li><li>Linux/macOS: <code>dlopen</code>, <code>dlsym</code>, <code>dlclose</code>, 错误通过 <code>dlerror()</code>。</li><li>搭配 <code>std::filesystem</code> 实现插件目录扫描。</li></ul><h2 id="_3-插件接口约定" tabindex="-1"><a class="header-anchor" href="#_3-插件接口约定"><span>3. 插件接口约定</span></a></h2><p>每个插件需导出一个标准 C 函数，供主程序调用。例如：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">extern</span> <span class="token string">&quot;C&quot;</span> <span class="token keyword">bool</span> <span class="token function">RegisterBeans</span><span class="token punctuation">(</span>ApplicationContext<span class="token operator">&amp;</span> ctx<span class="token punctuation">,</span> <span class="token keyword">const</span> PluginConfig<span class="token operator">&amp;</span> cfg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>PluginConfig</code> 由主程序解析配置后传入（包含运行环境、连接字符串等）。</li><li>插件在 <code>RegisterBeans</code> 里创建并注册自己的 Bean（例如 <code>MySQLDatabaseBean</code>、<code>RedisClientBean</code>）。</li><li>若需要自定义生命周期，可在 Bean 的 <code>OnInit/OnStart/OnStop</code> 内实现。</li></ul><p>插件示例（MySQL）：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">extern</span> <span class="token string">&quot;C&quot;</span> <span class="token keyword">bool</span> <span class="token function">RegisterBeans</span><span class="token punctuation">(</span>ApplicationContext<span class="token operator">&amp;</span> ctx<span class="token punctuation">,</span> <span class="token keyword">const</span> PluginConfig<span class="token operator">&amp;</span> cfg<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">auto</span> mysqlBean <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span><span class="token generic-function"><span class="token function">make_shared</span><span class="token generic class-name"><span class="token operator">&lt;</span>MySQLDatabaseBean<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span>mysql<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    ctx<span class="token punctuation">.</span><span class="token function">RegisterBean</span><span class="token punctuation">(</span><span class="token string">&quot;MySQLDatabase&quot;</span><span class="token punctuation">,</span> mysqlBean<span class="token punctuation">,</span> <span class="token comment">/*deps=*/</span><span class="token punctuation">{</span><span class="token string">&quot;LoggerBean&quot;</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-启动流程" tabindex="-1"><a class="header-anchor" href="#_4-启动流程"><span>4. 启动流程</span></a></h2><ol><li>解析配置文件/命令行，确定需要加载的插件列表（例如 <code>plugins/database/mysql_plugin.so</code>）。</li><li>对每个插件路径调用 <code>SharedLibrary::Load</code>，查询 <code>RegisterBeans</code> 符号。</li><li>调用 <code>RegisterBeans</code> 将 Bean 注册到 <code>ApplicationContext</code>。</li><li>完成所有插件注册后，进入 <code>ApplicationContext::Startup()</code>（按依赖/优先级启动）。</li></ol><p>可选：支持目录扫描和自动加载，以 <code>*.so</code>/<code>*.dll</code> 命名规则识别。</p><h2 id="_5-数据源插件应用" tabindex="-1"><a class="header-anchor" href="#_5-数据源插件应用"><span>5. 数据源插件应用</span></a></h2><table><thead><tr><th>插件</th><th>提供 Bean</th><th>依赖</th><th>说明</th></tr></thead><tbody><tr><td><code>mysql_plugin</code></td><td><code>MySQLDatabaseBean</code></td><td>Logger, ConfigLoader</td><td>内部链接 <code>libmysqlclient</code></td></tr><tr><td><code>redis_plugin</code></td><td><code>RedisClientBean</code></td><td>Logger, ConfigLoader, Transport</td><td>链接 <code>hiredis</code></td></tr><tr><td><code>mongo_plugin</code></td><td><code>MongoClientBean</code></td><td>Logger, ConfigLoader</td><td>链接 <code>mongocxx</code></td></tr><tr><td><code>clickhouse_plugin</code> (可选)</td><td><code>ClickHouseClientBean</code></td><td>Logger, ConfigLoader</td><td>等</td></tr></tbody></table><p>主程序只需面向 <code>IDatabase</code>/<code>ICache</code> 接口编程，插件将具体实现注入即可。</p><h2 id="_6-安全-版本控制" tabindex="-1"><a class="header-anchor" href="#_6-安全-版本控制"><span>6. 安全/版本控制</span></a></h2><ul><li>插件需遵守约定的 ABI（例如只有纯虚接口或 C 函数），避免 STL/模板跨边界。</li><li>可选：在插件包中附带版本、签名信息，主程序校验后才加载。</li><li>记录插件加载日志，便于诊断。</li></ul><h2 id="_7-roadmap" tabindex="-1"><a class="header-anchor" href="#_7-roadmap"><span>7. Roadmap</span></a></h2><ol><li>完成 <code>SharedLibrary</code> 封装与基本注册流程。</li><li>抽象 <code>IDatabase</code>, <code>ICache</code>, <code>ISocialModule</code> 等接口。</li><li>实现首批插件：MySQL、Redis、Mongo（根据项目优先级）。</li><li>扩展自动扫描/热加载、插件配置热更新。</li><li>引入安全/权限控制（签名、白名单）。</li></ol><hr><p>通过该机制，可以实现类似 Spring Boot Starter 的按需模块化，既满足“全部进程共享基础设施”的需求，也让不同服务能自由组合所需能力。***</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};